def adj_list(nodes, edges):
    adj = {v: [] for v in nodes}
    for u, v in edges:
        adj[u].append(v)
        if u != v:
            adj[v].append(u)
    for v in adj:
        adj[v].sort()
    return adj

def adj_matrix(n, edges):
    m = [[0] * n for _ in range(n)]
    for u, v in edges:
        m[u][v] = 1
        m[v][u] = 1
    return m

def find_ccp(n, posts):
    into = [0] * n
    out = [0] * n
    for a, b in posts:
        out[a] += 1
        into[b] += 1
    for f in range(n):
        if into[f] == n - 1 and out[f] == 0:
            return f
    return -1
